static void fx4_store_cases(size_t first, size_t n, const char *what)
{
    size_t i;
    int bad = 0;

    for (i = first; i < first + n; i++) {
        bad += fx4_store_case(&fx4_partial[i]);
    }
    TEST_CHECK(bad == 0);
    TEST_MSG("%s: %d of %d checks failed", what, bad, (int)(3 * n));
}

