/*
 * ---- NoVmp U2000-U2002: plan 1.K.8 (P12) - every built-in Intel model presents ONE cache model in CPUID 2, 4 and
 * 80000006H (kc_) ----
 * SDM 253665-093 Vol1 Table 21-12 p. 21-19 (leaf 2 descriptor FFH: "use CPUID leaf 4 to query cache parameters"),
 * Table 21-14 p. 21-21 (leaf 4), Tables 21-95 / 21-96 p. 21-93 (80000006H ECX: L2 line size [7:0], associativity
 * [15:12], size in 1K units [31:16]; EAX, EBX, EDX reserved). Upstream QEMU 6699e5dc86 / fe77a78149 (leaf 2) and
 * 63dc9f52f6 (80000006H). RED before U2000 / U2001: leaf 2 reported a 2 MB 8-way L2 (7DH) and 80000006H a 512 KB L2
 * beside the 4 MB 16-way L2 of leaf 4 (the Emulator\tools\cpuid_consistency.py view emu:max showed both).
 */
static void kc_cpuid(uc_engine *uc, uint32_t leaf, uint32_t sub, uint32_t r[4])
{
    static const int regs[4] = {UC_X86_REG_EAX, UC_X86_REG_EBX, UC_X86_REG_ECX, UC_X86_REG_EDX};
    int i;

    OK(uc_reg_write(uc, UC_X86_REG_EAX, &leaf));
    OK(uc_reg_write(uc, UC_X86_REG_ECX, &sub));
    OK(uc_emu_start(uc, code_start, code_start + 2, 0, 0));
    for (i = 0; i < 4; i++) {
        r[i] = 0;
        OK(uc_reg_read(uc, regs[i], &r[i]));
    }
}

/* the 80000006H / Table 21-96 associativity code of a way count (0 = no code for it) */
static uint32_t kc_assoc_code(uint32_t ways)
{
    static const uint32_t w[] = {1, 2, 4, 8, 16, 32, 48, 64, 96, 128};
    static const uint32_t c[] = {1, 2, 4, 6, 8, 0xA, 0xB, 0xC, 0xD, 0xE};
    size_t i;

    for (i = 0; i < sizeof(w) / sizeof(w[0]); i++) {
        if (w[i] == ways) {
            return c[i];
        }
    }
    return 0;
}

static void test_x86_kc_cache_models(void)
{
    int model, intel = 0, checked2 = 0, checked6 = 0;

    for (model = 0; model < UC_CPU_X86_ENDING; model++) {
        uc_engine *uc;
        uint32_t r0[4], r2[4], r4[4], rx[4], r6[4], sub, l2_kb = 0, l2_ways = 0, l2_line = 0;
        int has4 = 0;

        OK(uc_open(UC_ARCH_X86, UC_MODE_64, &uc));
        OK(uc_ctl_set_cpu_model(uc, model));
        OK(uc_mem_map(uc, code_start, code_len, UC_PROT_ALL));
        OK(uc_mem_write(uc, code_start, "\x0f\xa2", 2));
        kc_cpuid(uc, 0, 0, r0);
        if (!(r0[1] == 0x756e6547 && r0[3] == 0x49656e69 && r0[2] == 0x6c65746e)) {   /* not GenuineIntel */
            OK(uc_close(uc));
            continue;
        }
        intel++;
        if (r0[0] >= 4) {
            for (sub = 0; sub < 8; sub++) {
                kc_cpuid(uc, 4, sub, r4);
                if (!(r4[0] & 31)) {
                    break;
                }
                has4 = 1;
                if (((r4[0] >> 5) & 7) == 2 && (r4[0] & 31) == 3) {
                    l2_ways = (r4[1] >> 22) + 1;
                    l2_line = (r4[1] & 0xfff) + 1;
                    l2_kb = l2_ways * (((r4[1] >> 12) & 0x3ff) + 1) * l2_line * (r4[2] + 1) / 1024;
                }
            }
        }
        if (has4) {
            kc_cpuid(uc, 2, 0, r2);
            checked2++;
            TEST_CHECK(r2[0] == 1 && r2[1] == 0 && r2[2] == 0 && r2[3] == 0xff);
            TEST_MSG("model %d: CPUID 2 = %08x %08x %08x %08x, expected EAX 1, EBX 0, ECX 0, EDX FFH (leaf 4 present: descriptor FFH)",
                     model, r2[0], r2[1], r2[2], r2[3]);
        }
        kc_cpuid(uc, 0x80000000, 0, rx);
        if (rx[0] >= 0x80000006 && l2_kb) {
            kc_cpuid(uc, 0x80000006, 0, r6);
            checked6++;
            TEST_CHECK(r6[0] == 0 && r6[1] == 0 && r6[3] == 0 && (r6[2] >> 16) == l2_kb && (r6[2] & 0xff) == l2_line &&
                       ((r6[2] >> 12) & 0xf) == kc_assoc_code(l2_ways));
            TEST_MSG("model %d: CPUID 80000006H = %08x %08x %08x %08x; leaf 4 L2 %u KB %u-way %u-byte lines (expected ECX %08x, "
                     "EAX / EBX / EDX 0)", model, r6[0], r6[1], r6[2], r6[3], l2_kb, l2_ways, l2_line,
                     (l2_kb << 16) | (kc_assoc_code(l2_ways) << 12) | l2_line);
        }
        OK(uc_close(uc));
    }
    TEST_CHECK(intel >= 20 && checked2 >= 15 && checked6 >= 15);
    TEST_MSG("Intel models %d, leaf 2 checked on %d, 80000006H on %d (expected at least 20 / 15 / 15)", intel, checked2, checked6);
}

/* the MAX model as the K8 tool sees it: leaf 2 FFH and 80000006H = the leaf-4 L2; a CPUID profile still decides (rows as captured) */
static void test_x86_kc_max_profile(void)
{
    uc_engine *uc;
    uint32_t r[4];
    static const uc_x86_cpuid p[] = {
        {0, 0, 0x20, 0x756e6547, 0x6c65746e, 0x49656e69},
        {2, 0, 0x00feff01, 0, 0, 0x007d2c30},
        {0x80000000, 0, 0x80000008, 0, 0, 0},
        {0x80000006, 0, 0, 0, 0x02008040, 0},
    };

    OK(uc_open(UC_ARCH_X86, UC_MODE_64, &uc));
    OK(uc_ctl_set_cpu_model(uc, UC_CPU_X86_MAX));
    OK(uc_ctl_set_x86_cpuid(uc, p, sizeof(p) / sizeof(p[0])));
    OK(uc_mem_map(uc, code_start, code_len, UC_PROT_ALL));
    OK(uc_mem_write(uc, code_start, "\x0f\xa2", 2));
    kc_cpuid(uc, 2, 0, r);
    TEST_CHECK(r[0] == 0x00feff01 && r[3] == 0x007d2c30);
    TEST_MSG("profile leaf 2 = %08x .. %08x: the profile row is returned as given (captured data is never changed)", r[0], r[3]);
    kc_cpuid(uc, 0x80000006, 0, r);
    TEST_CHECK(r[2] == 0x02008040);
    TEST_MSG("profile 80000006H ECX = %08x, expected the row 02008040", r[2]);
    OK(uc_close(uc));
}
/* ---- end U2000-U2002 (kc_) ---- */

/* ---- U2043 (xpg_): lazy flags kept when the NEXT instruction crosses a page (P37, the sample's #GP) ---- */
/*
 * The translator restarts an instruction that crosses into the next page in a new TB (advance_pc, siglongjmp 2). The
 * flags of the instruction before it must survive that restart: XOR clears CF and OF and sets SF / ZF / PF from the
 * result (334569-093 Vol2D p. 6-41 XOR "Flags Affected"); ADC adds CF (253666-093 Vol2A p. 3-10 ADC "Operation":
 * DEST := DEST + SRC + CF).
 * Layout (own bytes): 4 x NOP at 1FF3H, XOR R11, RSI at 1FF7H, MOV RAX, 0 at 1FFAH (7 bytes: crosses into 2000H),
 * ADC R8, 8 at 2001H, SETC BL / SETS CL / SETZ DL after it.
 */
static int xpg_even_parity(unsigned v)
{
    int n = 0;
    for (int i = 0; i < 8; i++) {
        n += (v >> i) & 1;
    }
    return (n & 1) == 0;
}

static void xpg_nohook(uc_engine *uc, uint64_t address, uint32_t size, void *user_data)
{
    (void)uc; (void)address; (void)size;
    (*(int *)user_data)++;
}

static void xpg_run(int hook, uint64_t r11, uint64_t rsi, uint64_t fl, uint64_t *r8, uint64_t *rbx, uint64_t *rcx, uint64_t *rdx, uint64_t *flags_after)
{
    /* 1FF3: 90 x4 | 1FF7: 4C 33 DE xor r11, rsi | 1FFA: 48 C7 C0 00000000 mov rax, 0 | 2001: 49 81 D0 08000000 adc r8, 8 |
       2008: 0F 92 C3 setc bl | 200B: 0F 98 C1 sets cl | 200E: 0F 94 C2 setz dl | 2011 */
    static const char code[] = "\x90\x90\x90\x90\x4c\x33\xde\x48\xc7\xc0\x00\x00\x00\x00\x49\x81\xd0\x08\x00\x00\x00"
                               "\x0f\x92\xc3\x0f\x98\xc1\x0f\x94\xc2";
    uc_engine *uc;
    uc_hook h;
    int n = 0;
    uint64_t v = 0x1ff3, z = 0, f = fl, base = 0xfff100;
    OK(uc_open(UC_ARCH_X86, UC_MODE_64, &uc));
    OK(uc_mem_map(uc, 0x1000, 0x2000, UC_PROT_ALL));
    OK(uc_mem_write(uc, v, code, sizeof(code) - 1));
    OK(uc_reg_write(uc, UC_X86_REG_R11, &r11));
    OK(uc_reg_write(uc, UC_X86_REG_RSI, &rsi));
    OK(uc_reg_write(uc, UC_X86_REG_R8, &base));
    OK(uc_reg_write(uc, UC_X86_REG_RBX, &z));
    OK(uc_reg_write(uc, UC_X86_REG_RCX, &z));
    OK(uc_reg_write(uc, UC_X86_REG_RDX, &z));
    OK(uc_reg_write(uc, UC_X86_REG_RFLAGS, &f));
    if (hook) {
        OK(uc_hook_add(uc, &h, UC_HOOK_CODE, xpg_nohook, &n, 1, 0));
    }
    OK(uc_emu_start(uc, v, v + sizeof(code) - 1, 0, 0));
    OK(uc_reg_read(uc, UC_X86_REG_R8, r8));
    OK(uc_reg_read(uc, UC_X86_REG_RBX, rbx));
    OK(uc_reg_read(uc, UC_X86_REG_RCX, rcx));
    OK(uc_reg_read(uc, UC_X86_REG_RDX, rdx));
    OK(uc_reg_read(uc, UC_X86_REG_RFLAGS, flags_after));
    if (hook) {
        TEST_CHECK(n == 10);
        TEST_MSG("code hook calls %d, expected 10 (one per instruction)", n);
    }
    OK(uc_close(uc));
}

static void xpg_check(int hook, uint64_t r11, uint64_t rsi, uint64_t fl)
{
    uint64_t r8, bl, cl, dl, fa, res = r11 ^ rsi;
    xpg_run(hook, r11, rsi, fl, &r8, &bl, &cl, &dl, &fa);
    TEST_CHECK(r8 == 0xfff108 && bl == 0);
    TEST_MSG("hook %d, r11 %llx ^ rsi %llx, start flags %llx: ADC r8, 8 = %llx (expected FFF108H: CF = 0 after XOR), "
             "SETC after ADC = %llu (expected 0)", hook, (unsigned long long)r11, (unsigned long long)rsi,
             (unsigned long long)fl, (unsigned long long)r8, (unsigned long long)bl);
    /* ADC r8, 8 (FFF100H + 8, no carry): SF = 0, ZF = 0 */
    TEST_CHECK(cl == 0 && dl == 0);
    TEST_MSG("hook %d: SETS / SETZ after ADC = %llu / %llu (expected 0 / 0); XOR result %llx", hook, (unsigned long long)cl,
             (unsigned long long)dl, (unsigned long long)res);
}

static void xpg_xor_then_crossing_insn(void)
{
    /* the sample's operands (P37: #586995) and start flags; then other start flags / results */
    xpg_check(1, 0x11fd0c6d0ULL, 0x9617201fULL, 0x216);
    xpg_check(0, 0x11fd0c6d0ULL, 0x9617201fULL, 0x216);
    xpg_check(1, 0x11fd0c6d0ULL, 0x9617201fULL, 0x8d7);
    xpg_check(1, 1, 1, 0x216);
    xpg_check(1, 0x8000000000000000ULL, 0, 0x2d7);
}

/* XOR's own flags read through SETcc right after the crossing instruction (no ADC in between) */
static void xpg_xor_flags_survive(void)
{
    /* 1FF3: 90 x4 | 1FF7: 4C 33 DE xor r11, rsi | 1FFA: 48 C7 C0 00000000 mov rax, 0 (crosses) | 2001: 0F 92 C3 setc bl |
       2004: 0F 90 C1 seto cl | 2007: 0F 94 C2 setz dl | 200A: 0F 98 C0 sets al | 200D: 0F 9A C4 setp ah | 2010 */
    static const char code[] = "\x90\x90\x90\x90\x4c\x33\xde\x48\xc7\xc0\x00\x00\x00\x00\x0f\x92\xc3\x0f\x90\xc1\x0f\x94\xc2"
                               "\x0f\x98\xc0\x0f\x9a\xc4";
    static const struct { uint64_t r11, rsi, fl; } t[] = {
        { 0x11fd0c6d0ULL, 0x9617201fULL, 0x216 }, { 1, 1, 0x8d7 }, { 0x8000000000000000ULL, 0, 0x216 }, { 0xff, 0, 0x2 } };
    for (size_t i = 0; i < sizeof(t) / sizeof(t[0]); i++) {
        for (int hook = 0; hook < 2; hook++) {
            uc_engine *uc;
            uc_hook h;
            int n = 0;
            uint64_t v = 0x1ff3, z = 0, f = t[i].fl, a, b, c, d, res = t[i].r11 ^ t[i].rsi;
            uint64_t r11 = t[i].r11, rsi = t[i].rsi;
            int pf = xpg_even_parity((unsigned)(res & 0xff));
            OK(uc_open(UC_ARCH_X86, UC_MODE_64, &uc));
            OK(uc_mem_map(uc, 0x1000, 0x2000, UC_PROT_ALL));
            OK(uc_mem_write(uc, v, code, sizeof(code) - 1));
            OK(uc_reg_write(uc, UC_X86_REG_R11, &r11));
            OK(uc_reg_write(uc, UC_X86_REG_RSI, &rsi));
            OK(uc_reg_write(uc, UC_X86_REG_RBX, &z));
            OK(uc_reg_write(uc, UC_X86_REG_RCX, &z));
            OK(uc_reg_write(uc, UC_X86_REG_RDX, &z));
            OK(uc_reg_write(uc, UC_X86_REG_RFLAGS, &f));
            if (hook) {
                OK(uc_hook_add(uc, &h, UC_HOOK_CODE, xpg_nohook, &n, 1, 0));
            }
            OK(uc_emu_start(uc, v, v + sizeof(code) - 1, 0, 0));
            OK(uc_reg_read(uc, UC_X86_REG_RAX, &a));
            OK(uc_reg_read(uc, UC_X86_REG_RBX, &b));
            OK(uc_reg_read(uc, UC_X86_REG_RCX, &c));
            OK(uc_reg_read(uc, UC_X86_REG_RDX, &d));
            /* CF = OF = 0; ZF = (res == 0); SF = bit 63; PF = even parity of bits 7:0 */
            TEST_CHECK((b & 0xff) == 0 && (c & 0xff) == 0 && (d & 0xff) == (res == 0) && (a & 0xff) == (res >> 63) &&
                       ((a >> 8) & 0xff) == (uint64_t)pf);
            TEST_MSG("hook %d, %llx ^ %llx (start flags %llx): CF %llu OF %llu ZF %llu SF %llu PF %llu, expected 0 0 %d %d %d",
                     hook, (unsigned long long)t[i].r11, (unsigned long long)t[i].rsi, (unsigned long long)t[i].fl,
                     (unsigned long long)(b & 0xff), (unsigned long long)(c & 0xff), (unsigned long long)(d & 0xff),
                     (unsigned long long)(a & 0xff), (unsigned long long)((a >> 8) & 0xff), res == 0, (int)(res >> 63), pf);
            OK(uc_close(uc));
        }
    }
}
/* ---- end U2043 (xpg_) ---- */

/* ---- U2045 (sj_): tb_gen_code's restart bound read back after siglongjmp(jmp_trans, -2) (P38, the setjmp audit) ---- */
/*
 * tb_gen_code restarts a translation that runs out of TCGContext.temps (U450: every PSHUFD imm8
 * leaks a temp) with half its instruction bound, via siglongjmp(jmp_trans, -2) raised inside
 * gen_intermediate_code. Since U2045 (backport of upstream QEMU 344b63b380, setjmp_gen_code, never
 * inlined in our build) the sigsetjmp sits in its own small function that returns at once after the
 * jump, and the bound lives in tb_gen_code's frame: under MSVC sigsetjmp is the opaque
 * _setjmp_wrapper, the compiler sees an ordinary call and may reuse a local's stack slot while it is
 * dead in its view (U2043 lost cc_op that way; P38: the U2044 build kept max_insns' slot by allocation
 * only). Translation only (UC_CTL_TB_REQUEST_CACHE, nothing executed), SJ_N x PSHUFD xmm0, xmm0,
 * 39h at a page start: the bound 512 (TCG_MAX_INSNS) runs out of temps, one restart with 256 =
 * 512 / 2 fits, so the TB is exactly 256 instructions / 1280 bytes; the next TB the same.
 */
#define SJ_N 3001
#define SJ_BASE 0x100000

static void sj_tb_restart_halves(void)
{
    static const uint8_t pshufd0[5] = {0x66, 0x0f, 0x70, 0xc0, 0x39};
    uint8_t *code = (uint8_t *)malloc(SJ_N * 5);
    uc_engine *uc;
    uc_tb tb;
    int i;

    TEST_CHECK(code != NULL);
    if (!code) {
        return;
    }
    for (i = 0; i < SJ_N; i++) {
        memcpy(code + 5 * i, pshufd0, 5);
    }
    OK(uc_open(UC_ARCH_X86, UC_MODE_64, &uc));
    OK(uc_mem_map(uc, SJ_BASE, 0x20000, UC_PROT_ALL));
    OK(uc_mem_write(uc, SJ_BASE, code, SJ_N * 5));
    for (i = 0; i < 2; i++) {
        uint64_t pc = SJ_BASE + (uint64_t)i * 256 * 5;

        memset(&tb, 0, sizeof(tb));
        OK(uc_ctl_request_cache(uc, pc, &tb));
        TEST_CHECK(tb.pc == pc && tb.icount == 256 && tb.size == 256 * 5);
        TEST_MSG("TB %d: pc %llx icount %u size %u, expected pc %llx icount 256 size 1280", i,
                 (unsigned long long)tb.pc, (unsigned)tb.icount, (unsigned)tb.size, (unsigned long long)pc);
    }
    OK(uc_close(uc));
    free(code);
}
/* ---- end U2045 (sj_) ---- */

/*
 * ---- NoVmp U2090 / U2091 (plan 3.M6 "one virtual time base + RNG", notes/eread/P42_phase3_m6.md), helper prefix vc_ ----
 * U2090 UC_CTL_X86_VCLOCK: in virtual mode the TSC's time base = start + n * ticks_per_insn + advanced (n = the
 * instructions started since the control was written, counted by Unicorn's count hook also for count = 0); RDTSC,
 * RDMSR IA32_TIME_STAMP_COUNTER and IA32_TSC_ADJUST read the same counter; a uc_context restore never takes it back.
 * U2091: PBNDKB takes its random bytes from the RDRAND source (the seeded CTR_DRBG): deterministic per seed.
 */
/* rdtsc; shl rdx, 32; or rax, rdx; mov rbx, rax; nop; nop; nop; rdtsc; shl rdx, 32; or rax, rdx  (10 instructions) */
static const char vc_code[] = "\x0f\x31\x48\xc1\xe2\x20\x48\x09\xd0\x48\x89\xc3\x90\x90\x90"
                              "\x0f\x31\x48\xc1\xe2\x20\x48\x09\xd0";

static uc_engine *vc_open(void)
{
    uc_engine *uc;

    OK(uc_open(UC_ARCH_X86, UC_MODE_64, &uc));
    OK(uc_ctl_set_cpu_model(uc, UC_CPU_X86_MAX));
    OK(uc_mem_map(uc, code_start, 0x8000, UC_PROT_ALL));
    OK(uc_mem_write(uc, code_start, vc_code, sizeof(vc_code) - 1));
    return uc;
}

static void vc_run(uc_engine *uc, size_t count, uint64_t *first, uint64_t *second)
{
    OK(uc_emu_start(uc, code_start, code_start + sizeof(vc_code) - 1, 0, count));
    *first = nk_reg(uc, UC_X86_REG_RBX);
    *second = nk_reg(uc, UC_X86_REG_RAX);
}

/* U2090: the virtual time base counts instructions, across runs, with advances, restarts on a write */
static void test_x86_vc_virtual_rdtsc(void)
{
    uc_engine *uc = vc_open();
    uint64_t a, b, now = 1, n = 1;
    int mode = -1;

    OK(uc_ctl_get_x86_vclock(uc, &mode, &now, &n));
    TEST_CHECK(mode == UC_X86_VCLOCK_HOST && now == 0 && n == 0);     /* default: the host's counter, not reported */
    OK(uc_ctl_set_x86_vclock(uc, UC_X86_VCLOCK_VIRTUAL, 0x1000, 3));
    vc_run(uc, 0, &a, &b);
    TEST_CHECK(a == 0x1000 + 1 * 3 && b == 0x1000 + 8 * 3);            /* the 1st and the 8th instruction */
    TEST_MSG("a %" PRIx64 " b %" PRIx64, a, b);
    OK(uc_ctl_get_x86_vclock(uc, &mode, &now, &n));
    TEST_CHECK(mode == UC_X86_VCLOCK_VIRTUAL && n == 10 && now == 0x1000 + 10 * 3);
    TEST_MSG("n %" PRIu64 " now %" PRIx64, n, now);
    vc_run(uc, 0, &a, &b);                                             /* the next run continues the count */
    TEST_CHECK(a == 0x1000 + 11 * 3 && b == 0x1000 + 18 * 3);
    OK(uc_ctl_x86_vclock_advance(uc, 0x100));                          /* a wait: time passes without instructions */
    vc_run(uc, 0, &a, &b);
    TEST_CHECK(a == 0x1000 + 21 * 3 + 0x100 && b == 0x1000 + 28 * 3 + 0x100);
    vc_run(uc, 4, &a, &b);                                             /* a count bound: 4 instructions run */
    OK(uc_ctl_get_x86_vclock(uc, &mode, &now, &n));
    TEST_CHECK(a == 0x1000 + 31 * 3 + 0x100 && n == 34);
    TEST_MSG("bounded run: a %" PRIx64 " n %" PRIu64, a, n);
    OK(uc_ctl_set_x86_vclock(uc, UC_X86_VCLOCK_VIRTUAL, 5, 1));        /* a write restarts the count */
    vc_run(uc, 1000, &a, &b);                                          /* a bound larger than the code: the same values */
    TEST_CHECK(a == 5 + 1 && b == 5 + 8);
    OK(uc_close(uc));
}

/* U2090: invalid writes are refused; ADVANCE only in virtual mode, never wrapping */
static void test_x86_vc_args(void)
{
    uc_engine *uc = vc_open();
    uint64_t now = 0, n = 0;
    int mode = 0;

    TEST_CHECK(uc_ctl_set_x86_vclock(uc, 2, 0, 1) == UC_ERR_ARG);
    TEST_CHECK(uc_ctl_set_x86_vclock(uc, -1, 0, 1) == UC_ERR_ARG);
    TEST_CHECK(uc_ctl_set_x86_vclock(uc, UC_X86_VCLOCK_VIRTUAL, 0, 0) == UC_ERR_ARG);
    TEST_CHECK(uc_ctl_x86_vclock_advance(uc, 1) == UC_ERR_ARG);        /* host mode */
    TEST_CHECK(uc_ctl_get_x86_vclock(uc, NULL, &now, &n) == UC_ERR_ARG);
    OK(uc_ctl_set_x86_vclock(uc, UC_X86_VCLOCK_VIRTUAL, 0, 1));
    OK(uc_ctl_x86_vclock_advance(uc, ~0ULL - 1));
    TEST_CHECK(uc_ctl_x86_vclock_advance(uc, 2) == UC_ERR_ARG);        /* would wrap */
    OK(uc_ctl_set_x86_vclock(uc, UC_X86_VCLOCK_HOST, 0, 0));           /* back to the host's counter */
    OK(uc_ctl_get_x86_vclock(uc, &mode, &now, &n));
    TEST_CHECK(mode == UC_X86_VCLOCK_HOST && now == 0 && n == 0);
    OK(uc_close(uc));
}

/* U2090: RDMSR 10H, WRMSR IA32_TSC_ADJUST (3BH) and RDTSC read one counter; the control's 'now' excludes TSC_ADJUST */
static void test_x86_vc_msr_adjust(void)
{
    /* mov ecx, 10h; rdmsr; shl rdx, 32; or rax, rdx; mov rbx, rax; mov ecx, 3bh; mov eax, 500h; xor edx, edx; wrmsr;
       rdtsc; shl rdx, 32; or rax, rdx   (12 instructions) */
    static const char code[] = "\xb9\x10\x00\x00\x00\x0f\x32\x48\xc1\xe2\x20\x48\x09\xd0\x48\x89\xc3"
                               "\xb9\x3b\x00\x00\x00\xb8\x00\x05\x00\x00\x31\xd2\x0f\x30"
                               "\x0f\x31\x48\xc1\xe2\x20\x48\x09\xd0";
    uc_engine *uc;
    uint64_t now = 0, n = 0;
    int mode = 0;

    OK(uc_open(UC_ARCH_X86, UC_MODE_64, &uc));
    OK(uc_ctl_set_cpu_model(uc, UC_CPU_X86_MAX));
    OK(uc_ctl_set_x86_vclock(uc, UC_X86_VCLOCK_VIRTUAL, 0x10000, 2));
    OK(uc_mem_map(uc, code_start, 0x8000, UC_PROT_ALL));
    OK(uc_mem_write(uc, code_start, code, sizeof(code) - 1));
    OK(uc_emu_start(uc, code_start, code_start + sizeof(code) - 1, 0, 0));
    TEST_CHECK(nk_reg(uc, UC_X86_REG_RBX) == 0x10000 + 2 * 2);          /* RDMSR 10H is the 2nd instruction */
    TEST_CHECK(nk_reg(uc, UC_X86_REG_RAX) == 0x10000 + 10 * 2 + 0x500); /* RDTSC (10th) + IA32_TSC_ADJUST */
    TEST_MSG("rdmsr %" PRIx64 " rdtsc %" PRIx64, nk_reg(uc, UC_X86_REG_RBX), nk_reg(uc, UC_X86_REG_RAX));
    OK(uc_ctl_get_x86_vclock(uc, &mode, &now, &n));
    TEST_CHECK(n == 12 && now == 0x10000 + 12 * 2);
    OK(uc_close(uc));
}

/* U2090: a uc_context restore does not take the time base back (the TSC is monotonic, as U1620's wait ticks) */
static void test_x86_vc_context(void)
{
    uc_engine *uc = vc_open();
    uc_context *ctx;
    uint64_t a1, b1, a2, b2, a3, b3;

    OK(uc_ctl_set_x86_vclock(uc, UC_X86_VCLOCK_VIRTUAL, 0, 1));
    OK(uc_context_alloc(uc, &ctx));
    OK(uc_context_save(uc, ctx));
    vc_run(uc, 0, &a1, &b1);
    vc_run(uc, 0, &a2, &b2);
    OK(uc_context_restore(uc, ctx));
    vc_run(uc, 0, &a3, &b3);
    TEST_CHECK(a1 == 1 && a2 == 11 && a3 == 21 && b3 == 28);
    OK(uc_context_free(ctx));
    OK(uc_close(uc));
}

/*
 * U2091: PBNDKB's random values come from the RDRAND source (x86_rdrand_bytes): with the seeded CTR_DRBG (seed 0) the IV of
 * a KEY_GENERATION_CTRL = 1 bind is the model's values 9 and 10 (after the 64 key-randomization bytes = values 1-8) - known
 * answers of ref_ctr_drbg.py - and two engines write the same bind structure
 */
static void test_x86_vc_pbndkb_seeded(void)
{
    static const uint8_t iv_kat[12] = {0x36, 0x01, 0xda, 0x21, 0x80, 0xc6, 0xc6, 0xb5, 0x55, 0x22, 0x88, 0x91};
    const uint64_t in = SI_DATA + 0x1000, out = SI_DATA + 0x1100;
    uint8_t s[256], o[2][256];
    int i, e;
    SiCtx c;

    for (e = 0; e < 2; e++) {
        si_open(&c, 0, 0, 0, NULL, 0);
        for (i = 0; i < 256; i++) {
            s[i] = (uint8_t)(i * 5 + 1);
        }
        memset(s + 16, 0, 8);
        memset(s + 36, 0, 28);
        s[160] = 1;                                                    /* KEY_GENERATION_CTRL: randomize the keys */
        memset(s + 161, 0, 95);
        OK(uc_mem_write(c.uc, in, s, sizeof(s)));
        si_set(&c, UC_X86_REG_RBX, in);
        si_set(&c, UC_X86_REG_RCX, out);
        TEST_CHECK(si_run(&c, "\x0f\x01\xc7", 3) == -1);
        TEST_CHECK(si_get(&c, UC_X86_REG_RAX) == 0);
        OK(uc_mem_read(c.uc, out, o[e], sizeof(o[e])));
        OK(uc_close(c.uc));
    }
    TEST_CHECK(memcmp(o[0] + 24, iv_kat, 12) == 0);
    TEST_CHECK(memcmp(o[0], o[1], 256) == 0);
}

